```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <sstream>
#include <chrono>
#include <filesystem>
#include <nlohmann/json.hpp>  // JSON parsing library
#include <pqxx/pqxx>          // PostgreSQL database access
#include <boost/algorithm/string.hpp>  // String manipulation (lowercase, remove spaces)

using json = nlohmann::json;

std::mutex mtx;  // Mutex for thread-safe access to shared resources
std::vector<std::string> processed_files;  // Track processed files

/**
 * @brief Processes a single file (CSV/JSON) for data cleaning, analysis, and storage.
 * @param file_path Path to the file to process.
 */
void process_file(const std::string& file_path) {
    std::ifstream file(file_path);  // Open the file for reading
    std::string line;
    std::vector<std::map<std::string, std::string>> data;  // Store parsed data

    // Read file line by line and parse into key-value pairs
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::map<std::string, std::string> row;
        std::string key, value;
        while (iss >> key >> value) {
            row[key] = value;
        }
        data.push_back(row);
    }

    // Data cleaning: Sort by timestamp to ensure chronological order
    std::sort(data.begin(), data.end(), [](auto a, auto b) {
        return a["timestamp"] < b["timestamp"];
    });

    // Text standardization: Convert to lowercase and remove extra spaces
    for (auto& row : data) {
        std::string text = row["message"];
        boost::to_lower(text);  // Convert to lowercase
        boost::erase_all(text, " ", "");  // Remove extra spaces
        row["message"] = text;
    }

    // Database operations: Insert cleaned data into PostgreSQL
    try {
        pqxx::connection conn("dbname=postgres user=postgres password=secret host=localhost");
        pqxx::work txn(conn);
        for (const auto& row : data) {
            std::string query = "INSERT INTO chat_logs (timestamp, message) VALUES ('" + row["timestamp"] + "', '" + row["message"] + "')";
            txn.exec(query);  // Execute SQL query
        }
        txn.commit();  // Commit transaction
    } catch (const std::exception& e) {
        std::cerr << "DB error: " << e.what() << std::endl;  // Handle database errors
    }

    // Generate a CSV report of processed data
    std::ofstream report("report.csv");
    for (const auto& row : data) {
        report << row["timestamp"] << "," << row["message"] << "\n";
    }
    report.close();
}

/**
 * @brief Main function to orchestrate file processing.
 * - Iterates over files in the data directory.
 * - Launches threads to process files in parallel.
 * - Joins threads and prints completion message.
 */
int main() {
    std::filesystem::path data_dir("data");  // Directory containing input files
    std::vector<std::string> files;

    // Collect all CSV/JSON files from the data directory
    for (const auto& entry : std::filesystem::directory_iterator(data_dir)) {
        files.push_back(entry.path().string());
    }

    std::cout << "Processing " << files.size() << " files..." << std::endl;

    // Launch threads to process files in parallel
    std::vector<std::thread> threads;
    for (const auto& file : files) {
        threads.emplace_back(process_file, file);
    }

    // Wait for all threads to complete
    for (auto& t : threads) {
        t.join();
    }

    std::cout << "Processing complete!" << std::endl;
    return 0;
}
